package newcode_test

import (
	"reflect"
	"testing"

	"github.com/cristianargotti/golaw/internal/newcode"
	"github.com/cristianargotti/golaw/internal/proof"
	"github.com/cristianargotti/golaw/internal/surface"
)

const (
	golawGenerated = "// Code generated by golaw 0.3.0 kind=adapter-sql@1; DO NOT EDIT.\n\npackage postgres\n"
	sqlcGenerated  = "// Code generated by sqlc. DO NOT EDIT.\n// versions:\n//   sqlc v1.31.1\n\npackage sqlcgen\n"
	oapiGenerated  = "// Package apigen provides primitives to interact with the openapi HTTP API.\n//\n" +
		"// Code generated by github.com/oapi-codegen/oapi-codegen/v2 version v2.8.0 DO NOT EDIT.\npackage apigen\n"
)

// generatedTree holds a slice of the growth fixture: an owned adapter file,
// its regenerable file and contract test, and the two third party outputs.
func generatedTree() *proof.Tree {
	return proof.NewTree(map[string][]byte{
		"go.mod":                []byte("module example.test/slice\n\ngo 1.27\n"),
		"api/gen/server.gen.go": []byte(oapiGenerated),
		"internal/adapters/out/postgres/plans.go":                            []byte("package postgres\n"),
		"internal/adapters/out/postgres/sqlcgen/plans.sql.go":                []byte(sqlcGenerated),
		"internal/adapters/out/postgres/zz_generated_plans.go":               []byte(golawGenerated),
		"internal/adapters/out/postgres/zz_generated_plans_contract_test.go": []byte(golawGenerated),
	})
}

func TestUniverseCountsGeneratedCodeTheWayThePipelineDoes(t *testing.T) {
	t.Parallel()
	tree := generatedTree()
	for _, tc := range []struct {
		name  string
		scope surface.Scope
		want  []string
	}{
		{"red-no-scope-counts-the-golaw-files-and-leaves-third-party-output", resolved(t, surface.ScopeInput{Policy: analyzer(nil, nil)}), []string{
			"internal/adapters/out/postgres/plans.go", "internal/adapters/out/postgres/zz_generated_plans.go",
		}},
		{"red-an-inclusion-that-names-third-party-output-counts-it", surface.Scope{Inclusions: []string{"api/gen/**", "internal/**"}}, []string{
			"api/gen/server.gen.go", "internal/adapters/out/postgres/plans.go",
			"internal/adapters/out/postgres/sqlcgen/plans.sql.go", "internal/adapters/out/postgres/zz_generated_plans.go",
		}},
		{"near-the-pipeline-exclusions-drop-third-party-output", resolved(t, surface.ScopeInput{Policy: analyzer([]string{"**/gen/**", "**/sqlcgen/**"}, nil)}), []string{
			"internal/adapters/out/postgres/plans.go", "internal/adapters/out/postgres/zz_generated_plans.go",
		}},
		{"near-only-the-scope-drops-a-golaw-file", resolved(t, surface.ScopeInput{Policy: analyzer(nil, []string{"internal/adapters/out/postgres/zz_generated_plans.go"})}), []string{
			"internal/adapters/out/postgres/plans.go",
		}},
	} {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			if got := members(tree, newcode.Universe(tree, tc.scope)); !reflect.DeepEqual(got, tc.want) {
				t.Fatalf("universe = %q, want %q", got, tc.want)
			}
		})
	}
}
